pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address originalOwner;

    function setUp() public {
        c = new C();
        originalOwner = c.owner();
    }

    function testFuzz_property(address nonOwner, address newOwner) public {
        // Restrict nonOwner to be different from the original owner so the call is unauthorized
        vm.assume(nonOwner != originalOwner);
        // Ensure newOwner is not the zero address, but not strictly required
        vm.assume(newOwner != address(0));

        address currentOwnerBefore = c.owner();
        vm.prank(nonOwner);
        c.setOwner(newOwner);

        // After an unauthorized call, the correct contract keeps owner unchanged,
        // while the buggy contract sets owner to newOwner.
        assertTrue(c.owner() == currentOwnerBefore);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != newOwner);
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }
        // If setOwner did not revert, the returned success must be true.
        // The buggy version lets non-owner call succeed and still returns true,
        // so this passes on both. But we need a property the reference satisfies
        // and the bug breaks. The property: if the call does NOT revert,
        // the returned value is true. The reference: when caller != owner, it
        // reverts -> ok=false, the implication (no revert => success==true) holds
        // vacuously. When caller == owner, it succeeds and returns true -> holds.
        // The buggy version: always succeeds and returns true -> holds as well.
        // This property does NOT distinguish the bug. We need a different rule.
        // So we instead check: after any non-reverting setOwner, owner becomes newOwner.
        // The reference: only owner can cause non-reverting call, and it changes owner.
        // The buggy: anyone can, and it changes owner. Both satisfy this.
        // We need a rule that the reference satisfies but the bug breaks.
        // The reference satisfies: if caller != original owner and the call does NOT revert,
        // then impossible. That is, a non-owner call always reverts.
        // We can state: a non-owner call to setOwner will revert.
        // But the test must PASS on reference for ALL inputs, meaning even for owner calls.
        // So we need a rule that holds for ALL inputs on reference, and fails for some on buggy.
        // Rule: After setOwner is called by any caller, the returned value is true if and only if
        // the caller was the original owner. But the buggy version always returns true.
        // Let's test: In reference, if caller != owner, it reverts -> no return value to check.
        // So we can wrap in try/catch and check that if a non-owner call succeeds (does not revert),
        // then something must hold. But reference never has non-owner success, so "if non-owner succeeds"
        // is vacuously true for any consequence. That won't distinguish.
        // Actually we need a rule that the reference satisfies for EVERY input, and the bug breaks.
        // The reference: A call to setOwner by a non-owner will either revert or return true?
        // No, it only reverts. So the rule "setOwner does not revert for a non-owner" is false on reference,
        // so test would fail on reference. Not allowed.
        // The test must PASS on reference for ALL inputs. So we need a rule that is true on reference
        // for all inputs, but false on buggy for some input.
        // Consider: The reference satisfies that after setOwner is called, if it does not revert, then
        // the caller was the previous owner. The buggy version fails this because a non-owner can call
        // and it does not revert, so caller != previous owner, contradicting the implication.
        // We can state: (not reverted) => (caller == owner_before).
        // We need to capture owner_before. We can read owner before the call.
        // So:
        //   address ownerBefore = c.owner();
        //   vm.prank(caller);
        //   try c.setOwner(newOwner) returns (bool success) { reverted = false; } catch { reverted = true; }
        //   assertTrue(reverted || caller == ownerBefore);
        // This is true on reference: if not reverted, then caller == ownerBefore, because only owner can not revert.
        // If reverted, the condition is true. On buggy, a non-owner call succeeds (reverted = false) but caller != ownerBefore,
        // so the assertion fails. Perfect.
        address ownerBefore = c.owner();
        bool reverted;
        vm.prank(caller);
        try c.setOwner(newOwner) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted || caller == ownerBefore);
    }
}

