pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(_owner != address(0));
        // Ensure caller is the initial owner
        vm.prank(c.owner());
        c.setOwner(caller);
        // Now caller is owner, call setOwner with arbitrary _owner fuzzed
        vm.prank(caller);
        c.setOwner(_owner);
        // The general rule: after a successful setOwner, owner must equal the _owner argument
        assertTrue(c.owner() == _owner);
    }
}

