pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        vm.assume(msg.sender == c.owner());
        vm.prank(c.owner());
        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSignature("setOwner(address)", _owner));
        assertTrue(ok && abi.decode(ret, (bool)));
    }
}

